class Person {
  + identifying_number
  + name
  + address
}

class Employee extends Person {
}

class Owner extends Person {
  + phone
}

class Service {
  + car_km
  + hours_spent
  + admission_date
  + finish_date
}

class Car {
  + plate
  + make
  + model
  + color
}

class PartAcc {
  + serial_number
  + price
  + category
}

class CarModel {}

Employee "1" -- "*" Service : responsible
Service "*" -- "1" Car : executed_in
Service "1" -- "1..*" PartAcc : fitted_with
PartAcc "*" -- "1" CarModel : fits
Car "*" -- "1" Owner : owned_by
Car "*" -- "1" CarModel : is_a_model

@enduml

